342→// createCherryPickCommit creates a new commit on top of parent, preserving the
343→// original commit's message and author.
344→func createCherryPickCommit(repo *git.Repository, treeHash, parent plumbing.Hash, original *object.Commit) (plumbing.Hash, error) {
345→	committerName, committerEmail := GetGitAuthorFromRepo(repo)
346→	now := time.Now()
347→
348→	commit := &object.Commit{
349→		TreeHash:     treeHash,
350→		ParentHashes: []plumbing.Hash{parent},
351→		Author:       original.Author,
352→		Committer: object.Signature{
353→			Name:  committerName,
354→			Email: committerEmail,
355→			When:  now,
356→		},
357→		Message: original.Message,
358→	}
359→
360→	obj := repo.Storer.NewEncodedObject()
361→	if err := commit.Encode(obj); err != nil {
362→		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
363→	}
364→
365→	hash, err := repo.Storer.SetEncodedObject(obj)
366→	if err != nil {
367→		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
368→	}
369→
370→	return hash, nil
371→}
