573→func TestShadowStrategy_CanRewind_DirtyRepo(t *testing.T) {
574→	// For shadow, CanRewind always returns true because rewinding
575→	// replaces local changes with checkpoint contents - that's the expected behavior.
576→	// Users rewind to undo Claude's changes, which are uncommitted by definition.
577→	// However, it now returns a warning message with diff stats.
578→	dir := t.TempDir()
579→	repo, err := git.PlainInit(dir, false)
580→	if err != nil {
581→		t.Fatalf("failed to init git repo: %v", err)
582→	}
583→
584→	// Create initial commit
585→	worktree, err := repo.Worktree()
586→	if err != nil {
587→		t.Fatalf("failed to get worktree: %v", err)
588→	}
589→	testFile := filepath.Join(dir, "test.txt")
590→	if err := os.WriteFile(testFile, []byte("line1\nline2\nline3\n"), 0o644); err != nil {
591→		t.Fatalf("failed to write test file: %v", err)
592→	}
593→	if _, err := worktree.Add("test.txt"); err != nil {
594→		t.Fatalf("failed to add file: %v", err)
595→	}
596→	_, err = worktree.Commit("Initial commit", &git.CommitOptions{
597→		Author: &object.Signature{Name: "Test", Email: "test@test.com"},
598→	})
599→	if err != nil {
600→		t.Fatalf("failed to commit: %v", err)
601→	}
602→
603→	// Make the repo dirty by modifying the file
604→	if err := os.WriteFile(testFile, []byte("line1\nmodified line2\nline3\nnew line4\n"), 0o644); err != nil {
605→		t.Fatalf("failed to modify test file: %v", err)
606→	}
607→
608→	t.Chdir(dir)
609→
610→	s := NewManualCommitStrategy()
611→	can, reason, err := s.CanRewind(context.Background())
612→	if err != nil {
613→		t.Errorf("CanRewind() error = %v", err)
614→	}
615→	if !can {
616→		t.Error("CanRewind() = false, want true (shadow always allows rewind)")
617→	}
618→	// Now we expect a warning message with diff stats
619→	if reason == "" {
620→		t.Error("CanRewind() reason is empty, want warning about uncommitted changes")
621→	}
622→	if !strings.Contains(reason, "uncommitted changes will be reverted") {
623→		t.Errorf("CanRewind() reason = %q, want to contain 'uncommitted changes will be reverted'", reason)
624→	}
625→	if !strings.Contains(reason, "test.txt") {
626→		t.Errorf("CanRewind() reason = %q, want to contain filename 'test.txt'", reason)
627→	}
628→}
