105→	// Create files that would be deleted on rewind:
106→	// 1. A new untracked file (created after checkpoint)
107→	extraFile := filepath.Join(dir, "extra.js")
108→	if err := os.WriteFile(extraFile, []byte("console.log('extra');\n"), 0o644); err != nil {
109→		t.Fatalf("failed to write extra.js: %v", err)
