249→// TestShadowStrategy_Rewind_FromSubdirectory verifies that Rewind() writes files
250→// to the correct repo-root-relative locations when CWD is a subdirectory.
251→// This is a regression test for the bug where f.Name (repo-relative) was used
252→// directly with os.WriteFile, causing files to be written relative to CWD instead
253→// of the repo root.
254→func TestShadowStrategy_Rewind_FromSubdirectory(t *testing.T) {
255→	dir := t.TempDir()
256→	repo, err := git.PlainInit(dir, false)
257→	if err != nil {
258→		t.Fatalf("failed to init git repo: %v", err)
259→	}
260→
261→	worktree, err := repo.Worktree()
262→	if err != nil {
263→		t.Fatalf("failed to get worktree: %v", err)
264→	}
265→
266→	author := &object.Signature{
267→		Name:  "Test",
268→		Email: "test@example.com",
269→		When:  time.Now(),
270→	}
271→
272→	// Create initial commit with README.md
273→	if err := os.WriteFile(filepath.Join(dir, "README.md"), []byte("# Test\n"), 0o644); err != nil {
274→		t.Fatalf("failed to write README: %v", err)
275→	}
276→	if _, err := worktree.Add("README.md"); err != nil {
277→		t.Fatalf("failed to add README: %v", err)
278→	}
279→	initialCommit, err := worktree.Commit("Initial commit", &git.CommitOptions{Author: author})
280→	if err != nil {
281→		t.Fatalf("failed to create initial commit: %v", err)
282→	}
283→
284→	// Create files in nested directories for the checkpoint
285→	srcDir := filepath.Join(dir, "src")
286→	libDir := filepath.Join(dir, "src", "lib")
287→	if err := os.MkdirAll(libDir, 0o755); err != nil {
288→		t.Fatalf("failed to create lib dir: %v", err)
289→	}
290→
291→	appContent := "const app = 'hello';\n"
292→	utilsContent := "export function utils() {}\n"
293→
294→	if err := os.WriteFile(filepath.Join(srcDir, "app.js"), []byte(appContent), 0o644); err != nil {
295→		t.Fatalf("failed to write app.js: %v", err)
296→	}
297→	if err := os.WriteFile(filepath.Join(libDir, "utils.js"), []byte(utilsContent), 0o644); err != nil {
298→		t.Fatalf("failed to write utils.js: %v", err)
299→	}
300→
301→	if _, err := worktree.Add("src/app.js"); err != nil {
302→		t.Fatalf("failed to add src/app.js: %v", err)
303→	}
304→	if _, err := worktree.Add("src/lib/utils.js"); err != nil {
305→		t.Fatalf("failed to add src/lib/utils.js: %v", err)
306→	}
307→
308→	// Create checkpoint commit
309→	checkpointHash, err := worktree.Commit("Checkpoint with nested files", &git.CommitOptions{Author: author})
310→	if err != nil {
311→		t.Fatalf("failed to create checkpoint: %v", err)
312→	}
313→
314→	// Reset back to initial commit so the nested files are gone
315→	if err := worktree.Reset(&git.ResetOptions{
316→		Commit: initialCommit,
317→		Mode:   git.HardReset,
318→	}); err != nil {
319→		t.Fatalf("failed to reset to initial: %v", err)
320→	}
321→
322→	// Verify src directory is gone after reset
323→	if _, err := os.Stat(filepath.Join(dir, "src")); !os.IsNotExist(err) {
324→		t.Fatalf("expected src/ to not exist after reset, but it does")
325→	}
326→
327→	// Create a subdirectory and chdir into it (simulating agent running from subdirectory)
328→	frontendDir := filepath.Join(dir, "frontend")
329→	if err := os.MkdirAll(frontendDir, 0o755); err != nil {
330→		t.Fatalf("failed to create frontend dir: %v", err)
331→	}
332→	t.Chdir(frontendDir)
333→	paths.ClearWorktreeRootCache()
334→
335→	// Call Rewind from the subdirectory
336→	s := NewManualCommitStrategy()
337→	point := RewindPoint{
338→		ID:      checkpointHash.String(),
339→		Message: "Checkpoint with nested files",
340→		Date:    time.Now(),
341→	}
342→
343→	if err := s.Rewind(context.Background(), point); err != nil {
344→		t.Fatalf("Rewind() error = %v", err)
345→	}
346→
347→	// Verify files are restored at the REPO ROOT (not relative to CWD)
348→	restoredApp := filepath.Join(dir, "src", "app.js")
349→	content, err := os.ReadFile(restoredApp)
350→	if err != nil {
351→		t.Fatalf("expected src/app.js to exist at repo root, but got error: %v", err)
352→	}
353→	if string(content) != appContent {
354→		t.Errorf("src/app.js content = %q, want %q", string(content), appContent)
355→	}
356→
357→	restoredUtils := filepath.Join(dir, "src", "lib", "utils.js")
358→	content, err = os.ReadFile(restoredUtils)
359→	if err != nil {
360→		t.Fatalf("expected src/lib/utils.js to exist at repo root, but got error: %v", err)
361→	}
362→	if string(content) != utilsContent {
363→		t.Errorf("src/lib/utils.js content = %q, want %q", string(content), utilsContent)
364→	}
365→
366→	// Verify README.md is also restored at repo root
367→	content, err = os.ReadFile(filepath.Join(dir, "README.md"))
368→	if err != nil {
369→		t.Fatalf("expected README.md to exist at repo root, but got error: %v", err)
370→	}
371→	if string(content) != "# Test\n" {
372→		t.Errorf("README.md content = %q, want %q", string(content), "# Test\n")
373→	}
374→
375→	// Verify files are NOT written at CWD-relative paths (the bug behavior)
376→	wrongApp := filepath.Join(frontendDir, "src", "app.js")
377→	if _, err := os.Stat(wrongApp); !os.IsNotExist(err) {
378→		t.Errorf("src/app.js should NOT exist under frontend/ (CWD-relative), but it does at %s", wrongApp)
379→	}
380→
381→	wrongUtils := filepath.Join(frontendDir, "src", "lib", "utils.js")
382→	if _, err := os.Stat(wrongUtils); !os.IsNotExist(err) {
383→		t.Errorf("src/lib/utils.js should NOT exist under frontend/ (CWD-relative), but it does at %s", wrongUtils)
384→	}
385→}
